// Bootstrap authors the root of trust and the top-level targets rule file over
// store, staging and applying them to refs/gittuf/policy. It returns the
// applied policy commit ID.
//
// It needs exclusive write access to the policy and RSL references. Rollback
// reverts only the tips this call recorded, and a process that dies mid-call
// leaves its references behind.
func Bootstrap(ctx context.Context, store gitstore.Storer, p BootstrapParams) (githash.Hash, error) {
	state, err := authorState(ctx, p)
	if err != nil {
		return nil, err
	}

	for _, ref := range []string{Ref, StagingRef} {
		if _, err := store.GetReference(ref); err == nil {
			return nil, fmt.Errorf("policy already initialized on %s", ref)
		} else if !errors.Is(err, gitstore.ErrReferenceNotFound) {
			return nil, err
		}
	}

	// Bootstrap writes three references and the engine cannot undo them on a
	// first bootstrap: its reset paths restore a prior tip, and here there is
	// none. Without the rollback below, a failure part way through would leave
	// references that the check above then refuses to overwrite, so a transient
	// signing or backend fault would strand the repository with no way to retry.
	rslTip, hadRSL, err := referenceTip(store, rsl.Ref)
	if err != nil {
		return nil, err
	}

	var wrote bootstrapWrites

	if err := state.Commit(store, "Bootstrap gittuf policy", true, p.SignCommits); err != nil {
		// Commit sets the staging reference before it records the RSL entry,
		// and restores it only when a previous policy existed. A first
		// bootstrap has none, so a failed entry leaves it set.
		cause := recordWrite(store, StagingRef, &wrote.staging, fmt.Errorf("unable to stage policy: %w", err))
		return nil, rollbackBootstrap(store, rslTip, hadRSL, wrote, cause)
	}
	if err := recordWrites(store, &wrote); err != nil {
		return nil, rollbackBootstrap(store, rslTip, hadRSL, wrote, err)
	}

	if err := policy.Apply(ctx, store, p.SignCommits); err != nil {
		// Apply sets Ref before it records the RSL entry for it, and restores
		// only a previous tip, so a first bootstrap leaves Ref set.
		cause := recordWrite(store, Ref, &wrote.applied, fmt.Errorf("unable to apply policy: %w", err))
		return nil, rollbackBootstrap(store, rslTip, hadRSL, wrote, cause)
	}
	if err := recordWrites(store, &wrote); err != nil {
		return nil, rollbackBootstrap(store, rslTip, hadRSL, wrote, err)
	}

	appliedTip, err := store.GetReference(Ref)
	if err != nil {
		return nil, rollbackBootstrap(store, rslTip, hadRSL, wrote, fmt.Errorf("unable to read applied policy reference: %w", err))
	}

	return appliedTip, nil
}

// referenceTip reports ref's tip and whether it exists.
func referenceTip(store gitstore.Storer, ref string) (githash.Hash, bool, error) {
	tip, err := store.GetReference(ref)
	if err != nil {
		if errors.Is(err, gitstore.ErrReferenceNotFound) {
			return nil, false, nil
		}

		return nil, false, err
	}

	return tip, true, nil
}

// bootstrapWrites records what this call durably wrote. Rollback reverts these
// tips and nothing else.
//
// The tips are read back from the references rather than reported by the
// engine, which does not say what it wrote. That is only sound under
// Bootstrap's exclusive-access contract: a concurrent writer moving a
// reference between the write and the read would be recorded here as this
// call's own. See the follow-up tracked for carrying real write receipts.
type bootstrapWrites struct {
	staging githash.Hash
	applied githash.Hash
	rsl     githash.Hash
}

// referenceTipOrNil reports ref's tip, or nil when it does not exist.
func referenceTipOrNil(store gitstore.Storer, ref string) (githash.Hash, error) {
	tip, has, err := referenceTip(store, ref)
	if err != nil || !has {
		return nil, err
	}

	return tip, nil
}

// recordWrite reads ref's tip into dst so rollback can revert it, and reports
// cause. A read failure is joined onto cause rather than dropped: a tip this
// call cannot read is a reference it cannot roll back, and the caller must see
// why its cleanup was incomplete.
func recordWrite(store gitstore.Storer, ref string, dst *githash.Hash, cause error) error {
	tip, err := referenceTipOrNil(store, ref)
	if err != nil {
		return errors.Join(cause, fmt.Errorf("unable to read %s for rollback: %w", ref, err))
	}

	*dst = tip
	return cause
}

// recordWrites refreshes every tip rollback may need after a step succeeded.
func recordWrites(store gitstore.Storer, wrote *bootstrapWrites) error {
	for _, r := range []struct {
		ref string
		dst *githash.Hash
	}{{StagingRef, &wrote.staging}, {Ref, &wrote.applied}, {rsl.Ref, &wrote.rsl}} {
		tip, err := referenceTipOrNil(store, r.ref)
		if err != nil {
			return fmt.Errorf("unable to read %s for rollback: %w", r.ref, err)
		}
		*r.dst = tip
	}

	return nil
}

// rollbackBootstrap reverts what this Bootstrap wrote so it can be retried.
// Objects stay in the store, unreferenced. Cleanup failures join onto cause.
//
// Every revert is a compare-and-swap against the tip this call recorded. A
// reference holding some other value is left as it is and the refusal joins
// onto cause.
func rollbackBootstrap(store gitstore.Storer, rslTip githash.Hash, hadRSL bool, wrote bootstrapWrites, cause error) error {
	errs := []error{cause}

	for _, owned := range []struct {
		ref string
		tip githash.Hash
	}{{Ref, wrote.applied}, {StagingRef, wrote.staging}} {
		if owned.tip == nil {
			continue
		}
		if err := store.CheckAndDeleteReference(owned.ref, owned.tip); err != nil {
			errs = append(errs, fmt.Errorf("unable to roll back %s: %w", owned.ref, err))
		}
	}

	if wrote.rsl != nil {
		var err error
		if hadRSL {
			err = store.CheckAndSetReference(rsl.Ref, rslTip, wrote.rsl)
		} else {
			err = store.CheckAndDeleteReference(rsl.Ref, wrote.rsl)
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("unable to roll back %s: %w", rsl.Ref, err))
		}
	}

	return errors.Join(errs...)
}

// deleteReference removes ref, treating an absent reference as success.
func deleteReference(store gitstore.Storer, ref string) error {
	if err := store.DeleteReference(ref); err != nil && !errors.Is(err, gitstore.ErrReferenceNotFound) {
		return err
	}

	return nil
}

